    this->fill(buffer);
    ComCfg::FrameContext context;

    // Configure the driver to return a failure status
    this->m_sync_send_status = Drv::ByteStreamStatus::OTHER_ERROR;

    // Send data which should trigger a synchronous send that fails
    invoke_to_dataIn(0, buffer, context);

    // Verify that comStatusOut was called with FAILURE
    ASSERT_from_comStatusOut_SIZE(1);
    ASSERT_from_comStatusOut(0, Fw::Success::FAILURE);
}
```

